const row = Array.isArray($json) ? $json[0] : $json;
const cfg = row?.config || {};
const baseUrl = String(cfg.baseUrl || 'https://api.trychroma.com').replace(/\/+$/, '');
const tenant = String(cfg.tenant || 'My_Tenant').trim();
const database = String(cfg.database || 'QA-Documents-Chunk').trim();
const collection = String(cfg.collection || 'qa-chunks-batches').trim();
const topK = Math.max(1, Math.min(100, Number(cfg.topK) || 20));
const missing = [];
if (!tenant) missing.push('tenant');
if (!database) missing.push('database');
if (!collection) missing.push('collection');
const url = `${baseUrl}/api/v2/tenants/${encodeURIComponent(tenant || 'missing')}/databases/${encodeURIComponent(database || 'missing')}/collections/${encodeURIComponent(collection || 'missing')}`;
return [{ json: { url, config: { baseUrl, tenant, database, collection, topK }, settingsVersion: row?.settings_version || null, missing, enabled: row?.enabled !== false } }];

const now = new Date().toISOString();
function checkResult(nodeName, options = {}) {
  const successDetailBuilder = options.successDetailBuilder;
  const defaultOkDetail = options.defaultOkDetail || null;
  const downMessage = options.downMessage;
  try {
    const items = $items(nodeName);
    if (!items || items.length === 0) return { status: 'unreachable', detail: 'No response received' };
    const json = items[0].json || {};
    if (json.error || json.statusCode >= 400 || (typeof json.message === 'string' && json.message.toLowerCase().includes('error'))) {
      return { status: downMessage ? 'down' : 'error', detail: json.message || json.error?.message || JSON.stringify(json.error) || downMessage || 'Unknown error' };
    }
    if (successDetailBuilder) return { status: 'ok', detail: successDetailBuilder(json) };
    return { status: 'ok', detail: defaultOkDetail };
  } catch (e) {
    return { status: downMessage ? 'down' : 'unreachable', detail: e.message };
  }
}
const supabaseDb = checkResult('Check: Supabase DB', { successDetailBuilder: (json) => { const record = Array.isArray(json) ? json[0] : json; return record?.created_at ? `Last event: ${record.event} at ${record.created_at}` : 'Reachable, no records yet'; } });
const supabaseStorage = checkResult('Check: Supabase Storage', { successDetailBuilder: (json) => `Bucket "${json?.name || 'uploaded-project-docs'}" reachable` });
const chromaConfig = $('Build Chroma Health URL').first().json || {};
const chromaDb = chromaConfig.enabled === false || (Array.isArray(chromaConfig.missing) && chromaConfig.missing.length)
  ? { status: 'not_configured', detail: `ChromaDB settings incomplete: ${(chromaConfig.missing || []).join(', ')}` }
  : checkResult('Check: ChromaDB', { successDetailBuilder: (json) => { const vectorCount = json?.count_documents ?? 'unknown'; const collectionName = json?.name || chromaConfig.config?.collection || 'qa-chunks-batches'; const database = json?.database || chromaConfig.config?.database || 'QA-Documents-Chunk'; const topK = chromaConfig.config?.topK || 20; return `Collection "${collectionName}" in database "${database}" reachable. Vectors: ${vectorCount}. topK: ${topK}`; } });
const fastapiStatus = checkResult('Check: FastAPI Image Extractor', { downMessage: 'FastAPI extractor unreachable at :8000. Run: pm2 start doc-extractor', successDetailBuilder: (json) => json?.status || 'Reachable at http://127.0.0.1:8000' });
const converterStatus = checkResult('Check: MD->DOCX Converter Service', { downMessage: 'Converter service unreachable at :5050. Run: pm2 start format-converter', successDetailBuilder: (json) => json?.status || 'Reachable at http://127.0.0.1:5050' });
const allServices = [supabaseDb, supabaseStorage, chromaDb, fastapiStatus, converterStatus];
let overallStatus = 'ok';
if (allServices.some(s => ['down','unreachable','not_configured'].includes(s.status))) overallStatus = 'degraded';
if (allServices.some(s => s.status === 'error')) overallStatus = 'error';
const webhooks = { upload: '/webhook/upload-test-artifacts', ingestionStatus: '/webhook/job-status?jobId=...', generate: '/webhook/generate-qa-doc', generationStatus: '/webhook/job-status-retrieve?jobId=...', analytics: '/webhook/analytics-summary?pipeline=all&days=30', health: '/webhook/health', projects: '/webhook/projects', artifacts: '/webhook/artifacts', generatedDocuments: '/webhook/generated-documents', auditEvents: '/webhook/audit-events', settings: '/webhook/settings', integrationsStatus: '/webhook/integrations/status', integrationTest: '/webhook/integrations/{integrationKey}/test', integrationsTestAll: '/webhook/integrations/test-all' };
return [{ json: { status: overallStatus, generatedAt: now, environment: 'n8n', services: [ { name: 'n8n backend', status: 'ok', detail: 'Health workflow executed successfully' }, { name: 'Supabase DB', status: supabaseDb.status, detail: supabaseDb.detail }, { name: 'Supabase Storage', status: supabaseStorage.status, detail: supabaseStorage.detail }, { name: 'ChromaDB', status: chromaDb.status, detail: chromaDb.detail, config: chromaConfig.config || null }, { name: 'FastAPI Extractor', status: fastapiStatus.status, detail: fastapiStatus.detail }, { name: 'Converter Service', status: converterStatus.status, detail: converterStatus.detail }, { name: 'OpenAI', status: 'backend-managed', detail: 'Used by vision extraction, embeddings, and generation; not pinged to avoid costs' }, { name: 'Confluence', status: 'backend-managed', detail: 'Used inside generation workflow for document pages' }, { name: 'Jira', status: 'backend-managed', detail: 'Used inside generation workflow for user stories' } ], webhooks, integrations: { supabaseDb: supabaseDb.status, supabaseStorage: supabaseStorage.status, chromaDb: chromaDb.status, fastapiExtractor: fastapiStatus.status, converterService: converterStatus.status, openai: 'backend-managed', jira: 'backend-managed', confluence: 'backend-managed' } } }];
